def is_quadratic_residue(k, p=61):
    """Checks if k is a quadratic residue modulo p using Euler's criterion."""
    if k == 0:
        return True # Technically 0 is a QR, but we only check k=1 to 60 for this function
    # Euler's criterion: a^((p-1)/2) === (a/p) (mod p)
    return pow(k, (p - 1) // 2, p) == 1

def calculate_NL(k):
    """Calculates N_L(k) based on W1's distribution."""
    if k == 0:
        return 61

    # k must be in {1, ..., 60}
    if is_quadratic_residue(k):
        # 30 QRs
        return 62
    else:
        # 30 QNRs
        return 60

def calculate_NR(k):
    """Calculates N_R(k) based on W2's distribution."""
    # N_R(0) = 181.
    if k == 0:
        return 181

    # Group 1: N_R(k) = 60 (20 values)
    group_60 = {1, 3, 8, 9, 11, 20, 23, 24, 27, 28, 33, 34, 37, 38, 41, 50, 52, 53, 58, 60}
    if k in group_60:
        return 60

    # Group 2: N_R(k) = 45 (20 values)
    group_45 = {2, 5, 6, 7, 13, 15, 16, 18, 21, 22, 39, 40, 43, 45, 46, 48, 54, 55, 56, 59}
    if k in group_45:
        return 45

    # Group 3: N_R(k) = 72 (20 values)
    group_72 = {4, 10, 12, 14, 17, 19, 25, 26, 29, 30, 31, 32, 35, 36, 42, 44, 47, 49, 51, 57}
    if k in group_72:
        return 72

    # This case should not be reached if the lists cover 1 to 60.
    return 0 

